const decode=encoded=>{const bytes=atob(encoded),data=new Float32Array(bytes.length/2);for(let i=0;i<data.length;i++){let v=bytes.charCodeAt(i*2)|(bytes.charCodeAt(i*2+1)<<8);if(v>32767)v-=65536;data[i]=v/32768;}return data;};
export const AUDIO_KIT={
 kick:{rate:32000,loop:false,data:decode('')},
 snare:{rate:32000,loop:false,data:decode('')},
 snareAlt:{rate:32000,loop:false,data:decode('')},
 hat:{rate:32000,loop:false,data:decode('')},
 openHat:{rate:32000,loop:false,data:decode('')},
 crash:{rate:32000,loop:false,data:decode('')},
 metal:{rate:32000,loop:false,data:decode('')},
 piano:{rate:32000,loop:false,data:decode('')},
 switch:{rate:32000,loop:false,data:decode('')},
 click:{rate:32000,loop:false,data:decode('')},
 horn:{rate:24000,loop:true,data:decode('')},
 siren:{rate:24000,loop:true,data:decode('')},
};
